def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()
    write_time = {}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries that are in the cache
            expired_keys = [k for k, write_t in write_time.items() if write_t + ttl <= t]
            for k in expired_keys:
                if k in cache:
                    del cache[k]
                    del write_time[k]

            # If key already exists, remove it (will be re-added at end)
            if key in cache:
                del cache[key]
                del write_time[key]
            else:
                # Key is new, check if we need to evict
                if len(cache) >= capacity:
                    # Evict least recently used
                    lru_key, _ = cache.popitem(last=False)
                    del write_time[lru_key]

            # Add the new/updated entry at the end (most recently used)
            cache[key] = value
            write_time[key] = t

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and is not expired
            if key in cache and write_time[key] + ttl > t:
                results.append(cache[key])
                # Move to end (most recently used)
                cache.move_to_end(key)
            else:
                results.append(-1)

    return results

